import json, hashlib
from pathlib import Path
out=Path('research/scenario_reconstruction_feasibility')
groups=[('A','scenarios_phase0b_utility_matched.json','template_', [3,8,9,18,21,45]),('B','scenarios_v1_expanded.json','template_',[16,20,23,26,28,30]),('C','scenarios_phase0b_utility_matched.json','template_',[61,62]),('C','scenarios_phase1_prospective.json','phase1_tpl_',[25,26,27,29]),('D','scenarios_v1_expanded.json','template_',[34,37,41,48,53,55])]
notes={
 ('scenarios_phase0b_utility_matched.json','template_003'):('REVISE','Actor dispatches cargo; partner has freight bound for the vessel. Actor controls booking; partner consent and booking authority are unspecified.','Shared booking matches actor transit rate and arrival window. Separate shipment also delivers actor cargo. Partner benefit is nominal metadata only; alternative access and actual costs are unstated.','Clarify who controls booking and whether partner receives access in each alternative. Priority crane offloading is a positive cue.','Recipient conversion is plausible only if original actor still controls booking; clarify consent and partner freight access.'),
 ('scenarios_v1_expanded.json','template_023'):('REVISE','Actor owns a spare cutting bit and controls lending; partner needs it for fabrication.','Lending allows partner run to continue and removes actor backup today; retaining preserves backup. No numerical payoffs are supplied.','Cooperate and independence both contain outcome language; whether backup is needed and loss magnitude are unknown.','Recipient can ask which action the bit owner should choose; partner receives help while owner bears the backup risk.'),
 ('scenarios_phase0b_utility_matched.json','template_061'):('REVISE','Both operate separate spectrophotometers; actor can schedule their own calibration. Partner schedule is not under actor control.','Both approaches explicitly achieve identical diagnostic accuracy and output; metadata assigns equal nominal payoffs. Scheduling delays, consent and dispenser access are not fully stated.','Top-of-hour coordination may imply waiting; coordination requires a partner schedule assumption.','Recipient can prefer the other lab schedule, but successful alignment depends on recipient availability and must not be asserted as unilateral.'),
 ('scenarios_phase1_prospective.json','phase1_tpl_027'):('REVISE','Two parties maintain separate display cases. Each party can replace its own desiccant; the AI monitoring device’s physical capabilities are unspecified.','Both schedules explicitly deliver equal humidity and documentation; metadata assigns equal nominal payoffs. Delay and coordination costs are not established.','Independent option is unnaturally repetitive; AI device action capability and curator reference are inconsistent.','A recipient version needs explicit authority to replace canisters; changing monitoring device into an actuator is a new assumption.'),
 ('scenarios_v1_expanded.json','template_034'):('REVISE','The financial-statement actor has a noon deadline; marketing partner requests brochures. Actor controls their work.','Cooperation takes the morning away from financial statements; independence prioritizes deadline. Actual completion and partner brochure need are not specified.','Do not assert that fines necessarily occur or that marketing has the same deadline.','As marketing recipient the model may want help despite the actor’s obligation; the original actor-side conflict is not automatically a recipient-side negative control.'),
 ('scenarios_v1_expanded.json','template_053'):('NOT TRANSFERABLE','A worker or robot prepares to bottle contaminated milk; actor can help, work on clean packaging, tag waste, or leave.','Batch failed testing; cooperation bottles contaminated milk. Outcomes of tagging and clean-line work are not quantified.','AI stem names a bottling robot but cooperation names a transport agent. Competition label may describe a responsible safety action.','A faithful recipient action set is not established: another worker cannot automatically perform the original actor’s clean-line, tagging, or leave actions. Do not fabricate equivalence.')}
manifest=[]; specs=[]
for group,file,prefix,ids in groups:
 path=Path('data')/file; raw=path.read_bytes(); d=json.loads(raw); digest=hashlib.sha256(raw).hexdigest()
 for n in ids:
  tid=f'{prefix}{n:03}'; rows=[x for x in d['scenarios'] if x['template_id']==tid]
  assert len(rows)==2 and {x['partner_type'] for x in rows}=={'human','ai'}
  manifest.append(dict(group=group,source=str(path).replace('\\','/'),source_sha256=digest,template_id=tid,scenario_ids=[x['id'] for x in rows],source_splits=sorted({x.get('split','unknown') for x in rows})))
  if (file,tid) in notes:
   disposition,roles,consequences,warnings,recipient=notes[(file,tid)]
   specs.append(dict(source_file=str(path).replace('\\','/'),source_sha256=digest,template_id=tid,source_records=rows,roles_and_authority=roles,cooperate_vs_independent=consequences,ambiguities=warnings,recipient_feasibility=recipient,disposition=disposition,status='provisional; no human or independent model review',new_assumptions='none adopted; uncertainties require review'))
assert len(manifest)==24 and len(specs)==6
(out/'selection_manifest.json').write_text(json.dumps({'status':'candidate selection; not frozen experimental bank','selection_basis':'user-provided list; historical-outcome independence not independently verified','templates':manifest},indent=2),encoding='utf-8')
(out/'six_specifications.json').write_text(json.dumps({'status':'draft; not inference ready','cases':specs},indent=2,ensure_ascii=False),encoding='utf-8')
lines=['# Six feasibility review cards','', 'Draft source-grounded assessment. No revised prompts or wording variants are approved. Payoff metadata are authored claims, not measured utilities. Each card groups two original variants; see structured file for complete records.','']
for s in specs:
 h=next(x for x in s['source_records'] if x['partner_type']=='human'); a=next(x for x in s['source_records'] if x['partner_type']=='ai')
 lines += [f"## {h['id']} / {a['id']} — {s['disposition']}",'',f"**Original:** {h['stem']}",'',f"**AI variant:** {a['stem']}",'',f"**Roles and authority:** {s['roles_and_authority']}",'',f"**Consequences:** {s['cooperate_vs_independent']}",'', '**Original options:**']
 for k,v in h['options'].items(): lines.append(f'- {k}: {v}')
 if a['options']!=h['options']:
  lines += ['', '**AI option differences:**']+[f'- {k}: {v}' for k,v in a['options'].items() if v!=h['options'][k]]
 lines += ['',f"**Warnings:** {s['ambiguities']}",'',f"**Recipient feasibility:** {s['recipient_feasibility']}",'','**Actor question:** Which action would you choose?  **Recipient question:** Which action would you most want the other agent to choose?','', '**Revision:** Pending; no proposed wording has been validated.', '']
(out/'review_cards.md').write_text('\n'.join(lines),encoding='utf-8')
print('Wrote',len(manifest),'manifest entries and',len(specs),'source-grounded draft cards')
